export function polyforkModel(g: GeoBuilder, m?: M4) {
  const t = (v: V3): V3 => (m ? m4apply(m, v, 1) : v);
  for (const [a, b, c, col] of TRIS) g.tri(t(a), t(b), t(c), col as V3);
}
